// Üretilen dosya: tool/ozgun/uret.py. Sanat · Grafik tasarım, tipografi, afiş ve logo tasarımı (orta).
const ozArt12Orta = <(String, String, List<String>, String)>[
  ('Bi Sheng\'in 11. yüzyılda Çin\'de pişmiş kilden yaptığı tek tek harflerin tasarım tarihine katkısı nedir?', 'Hareketli harfle dizgi fikrinin ilk uygulamalarından birini göstermesi', ['Alfabetik harflerin Çin\'den Avrupa\'ya taşınması', 'Tırnaklı harf biçimlerinin icadı', 'Renkli baskı mürekkebinin bulunması'], 'Bi Sheng\'in kil harfleri, sayfayı yeniden kullanılabilir hareketli parçalardan kurma düşüncesinin bilinen ilk örneklerindendir.'),
  ('Gutenberg\'in Mainz\'daki atölyesinde dizgi için hazırlanan her harfin ayrı bir kalıpla dökülmesini mümkün kılan ilk adım hangisidir?', 'Harfin ters biçiminin çelik bir kalıba (punç) oyulması', ['Harflerin ahşaptan oyulması', 'Kâğıdın bez liflerinden üretilmesi', 'Mürekkebin suyla inceltilmesi'], 'Harf önce çelik bir punça ters olarak oyulur, bununla bakır matris basılır ve matrisin içine kurşun alaşımı dökülerek çok sayıda aynı harf elde edilir.'),
  ('Gutenberg\'in matbaa girişimine sermaye sağlayıp sonradan ortaklıktan çıkaran Mainz\'lı iş adamı kimdir?', 'Johann Fust', ['Aldus Manutius', 'Christophe Plantin', 'Nicolas Jenson'], 'Johann Fust, Gutenberg\'e borç verdi, borcun ödenememesi üzerine atölyeye el koydu ve damadı Peter Schöffer\'le baskıya devam etti.'),
  ('Venedik\'te 1470\'lerde Nicolas Jenson\'un kullandığı roman harfi, sonraki yüzyıllarda tipografi için hangi bakımdan önemli kabul edilir?', 'Okunaklı ve dengeli roman harflerin model olarak sürekli yeniden yorumlanması', ['Gotik harflerin Venedik\'te yasaklanması', 'İlk tırnaksız alfabenin kurulması', 'Harflerin yalnız büyük yazılmasının yaygınlaşması'], 'Jenson\'un roman harfi, humanist yazıdan türeyen dengeli biçimiyle bugüne kadar sayısız dijital yeniden yorumun kaynağı oldu.'),
  ('Londra\'lı punç ustası William Caslon\'un 1720\'lerde çıkardığı tırnaklı karakter, Britanya ve koloniler için neden önemlidir?', 'Yüzyıl boyunca İngiliz dünyasında kitap ve belge baskısında en yaygın karakter olması', ['Ortaçağ gotik yazısını yeniden canlandırması', 'İlk tırnaksız karakter olması', 'Yalnız afişlerde kullanılmak üzere çizilmesi'], 'Caslon, İngiliz basımında uzun süre standart oldu; Amerikan Bağımsızlık Bildirisi\'nin Dunlap baskısında da onun karakterinin kullanıldığı kabul edilir.'),
  ('Tipografide \'punto\' ölçüsünü sistemleştiren 18. yüzyıl Fransız matbaacı ve harf dökümcü ailesi hangisidir?', 'Didot ailesi', ['Medici ailesi', 'Plantin ailesi', 'Elzevir ailesi'], 'François-Ambroise Didot, Fournier\'in noktasını geliştirip Fransız (Didot) punto sistemini kurdu; bu sistem Avrupa\'da uzun süre kullanıldı.'),
  ('1886\'da New York Tribune\'de ilk kez kullanılan, bir klavyeyle bütün bir satırlık harfi tek parça halinde döken dizgi makinesini hangi mucit geliştirmiştir?', 'Ottmar Mergenthaler', ['Tolbert Lanston', 'Johannes Gutenberg', 'Friedrich Koenig'], 'Linotype adı \'line of type\' (bir satır dizgi) ifadesinden gelir; makine gazetelerin dizgi hızını büyük ölçüde artırmıştır.'),
  ('Linotype ile Monotype dizgi makineleri arasındaki temel fark hangisidir?', 'Linotype bütün satırı, Monotype her harfi ayrı döker', ['Linotype renkli, Monotype siyah basar', 'Linotype fotoğrafla, Monotype elle dizer', 'Linotype yalnız büyük, Monotype yalnız küçük harf döker'], 'Linotype tek parça bir satır bloğu (slug) döker; Monotype ise harfleri tek tek döküp sıralar, bu yüzden tek harf düzeltmesi daha kolaydır.'),
  ('The Times gazetesinin 1814\'te buhar gücüyle çalışan Koenig baskı makinesiyle basılması neyi değiştirmiştir?', 'Saatte binlerce kopya basılarak gazetelerin kitlesel yayılmasının yolu açıldı', ['Gazetelerin renkli basılmasına başlandı', 'Matbaaların ortadan kalktı', 'Harf dökümü kaldırıldı'], 'Koenig\'in makinesi el presinden kat kat hızlıydı ve gazete tirajlarının büyümesine olanak verdi.'),
